const parse = require('./parse.js')

const diff = (version1, version2) => {
  const v1 = parse(version1, null, true)
  const v2 = parse(version2, null, true)
  const comparison = v1.compare(v2)

  if (comparison === 0) {
    return null
  }

  const v1Higher = comparison > 0
  const highVersion = v1Higher ? v1 : v2
  const lowVersion = v1Higher ? v2 : v1

  const highHasPre = !!highVersion.prerelease.length
  const lowHasPre = !!lowVersion.prerelease.length

  // Stepping INTO a prerelease: the target (higher) version is a prerelease.
  if (highHasPre && !lowHasPre) {
    if (highVersion.major > lowVersion.major) {
      return 'premajor'
    } else if (highVersion.minor > lowVersion.minor) {
      return 'preminor'
    } else if (highVersion.patch > lowVersion.patch) {
      return 'prepatch'
    } else {
      return 'prerelease'
    }
  }

  // Stepping OUT of a prerelease: we are leaving a prerelease (lower) version.
  if (!highHasPre && lowHasPre) {
    // leaving a prerelease whose minor and patch are both zero is always a
    // 'major' step, regardless of whether the main version also changed.
    if (lowVersion.minor === 0 && lowVersion.patch === 0) {
      return 'major'
    }
    // when the main version is otherwise unchanged, classify by how much of
    // the main version is actually being left behind.
    if (highVersion.major === lowVersion.major &&
        highVersion.minor === lowVersion.minor &&
        highVersion.patch === lowVersion.patch) {
      if (lowVersion.minor !== 0 && lowVersion.patch === 0) {
        return 'minor'
      }
      return 'patch'
    }
  }

  // Both prereleases, both non-prereleases, or a step out of a prerelease
  // whose main version also changed: classify by the main version delta.
  const prefix = highHasPre ? 'pre' : ''

  if (v1.major !== v2.major) {
    return prefix + 'major'
  }

  if (v1.minor !== v2.minor) {
    return prefix + 'minor'
  }

  if (v1.patch !== v2.patch) {
    return prefix + 'patch'
  }

  // both are prereleases of the same main version
  return 'prerelease'
}

