class LRUCache {
  constructor () {
    this.max = 1000
    this.map = new Map()
  }

  get (key) {
    if (!this.map.has(key)) {
      return undefined
    }

    const value = this.map.get(key)
    this.map.delete(key)
    this.map.set(key, value)
    return value
  }

  delete (key) {
    return this.map.delete(key)
  }

  set (key, value) {
    if (value !== undefined) {
      if (this.map.has(key)) {
        this.map.delete(key)
      }

      this.map.set(key, value)

      if (this.map.size > this.max) {
        const oldest = this.map.keys().next().value
        this.map.delete(oldest)
      }
    }

    return this
  }
}

