const parse = require('./parse.js')

const diff = (version1, version2) => {
  const v1 = parse(version1, null, true)
  const v2 = parse(version2, null, true)
  const comparison = v1.compare(v2)

  if (comparison === 0) {
    return null
  }

  const v1Higher = comparison > 0
  const highVersion = v1Higher ? v1 : v2
  const lowVersion = v1Higher ? v2 : v1
  const highHasPre = !!highVersion.prerelease.length
  const lowHasPre = !!lowVersion.prerelease.length

  const compareMainResult = highVersion.compareMain(lowVersion)

  // Same main version: only prerelease status differs (or differs by prerelease).
  if (compareMainResult === 0) {
    // Two prereleases of the same main version.
    if (highHasPre && lowHasPre) {
      return 'prerelease'
    }

    // Stepping out of a prerelease: the main version is unchanged, so the
    // step is classified by how much of the main version is left behind.
    const pre = lowVersion
    if (pre.minor === 0 && pre.patch === 0) {
      return 'major'
    }
    if (pre.minor !== 0 && pre.patch === 0) {
      return 'minor'
    }
    return 'patch'
  }

  // Different main version: figure out the base release type from the
  // difference in the main version.
  let base
  if (highVersion.major !== lowVersion.major) {
    base = 'major'
  } else if (highVersion.minor !== lowVersion.minor) {
    base = 'minor'
  } else {
    base = 'patch'
  }

  // Stepping into a prerelease keeps the `pre` prefix.
  if (highHasPre && !lowHasPre) {
    return 'pre' + base
  }

  // Stepping out of a prerelease across a main-version change is still
  // classified by how much of the main version is left behind.
  if (!highHasPre && lowHasPre) {
    const pre = lowVersion
    if (pre.minor === 0 && pre.patch === 0) {
      return 'major'
    }
    if (pre.minor !== 0 && pre.patch === 0) {
      return 'minor'
    }
    return 'patch'
  }

  // Ordinary release step (neither version is a prerelease).
  return base
}

