const parse = require('./parse.js')

const mainDiff = (high, low) => {
  if (high.major !== low.major) {
    return 'major'
  }
  if (high.minor !== low.minor) {
    return 'minor'
  }
  return 'patch'
}

const diff = (version1, version2) => {
  const v1 = parse(version1, null, true)
  const v2 = parse(version2, null, true)
  const comparison = v1.compare(v2)

  if (comparison === 0) {
    return null
  }

  const v1Higher = comparison > 0
  const high = v1Higher ? v1 : v2
  const low = v1Higher ? v2 : v1

  const highHasPre = !!high.prerelease.length
  const lowHasPre = !!low.prerelease.length

  // both versions are prereleases
  if (highHasPre && lowHasPre) {
    if (high.compareMain(low) !== 0) {
      // stepping up into a higher prerelease main version
      return 'pre' + mainDiff(high, low)
    }
    // same main version, both prereleases
    return 'prerelease'
  }

  // exactly one version is a prerelease
  if (highHasPre !== lowHasPre) {
    // the prerelease and the release share the same main version: this is a
    // step out of (or into) that exact release. Classify by how much of the
    // main version is being left behind, with no `pre` prefix.
    if (high.compareMain(low) === 0) {
      if (high.minor === 0 && high.patch === 0) {
        return 'major'
      }
      if (high.minor !== 0 && high.patch === 0) {
        return 'minor'
      }
      return 'patch'
    }

    // main versions differ: stepping into a prerelease keeps the `pre` prefix
    if (highHasPre) {
      return 'pre' + mainDiff(high, low)
    }
    return mainDiff(high, low)
  }

  // neither version is a prerelease: an ordinary release step
  return mainDiff(high, low)
}

module.exports = diff
